import random
from collections import defaultdict, deque

def has_short_cycle(adj, n, max_len=7):
    """Check if graph has cycle of length <= max_len"""
    for start in range(n):
        # BFS from start
        parent = {start: -1}
        depth = {start: 0}
        q = deque([start])
        while q:
            u = q.popleft()
            if depth[u] >= (max_len + 1) // 2:
                continue
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent.get(u, -1) and parent.get(v, -1) != u:
                    # Found cycle
                    cycle_len = depth[u] + depth[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

def is_3_colorable(adj, n):
    """Check if graph is 3-colorable using backtracking"""
    colors = {}
    def dfs(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if u in colors:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(v+1):
                    return True
                del colors[v]
        return False
    return dfs(0)

