import random
from collections import defaultdict, deque
import time

n = 18
target_edges = 29

def has_short_cycle(adj, max_len=7):
    """Check if graph has cycle of length <= max_len"""
    for start in range(n):
        if start not in adj or len(adj[start]) == 0:
            continue
        parent = {start: -1}
        depth = {start: 0}
        q = deque([start])
        while q:
            u = q.popleft()
            if depth[u] >= (max_len + 1) // 2:
                continue
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent.get(u, -1) and parent.get(v, -1) != u:
                    cycle_len = depth[u] + depth[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

def is_3_colorable_fast(adj):
    """Check if graph is 3-colorable using DSATUR-like greedy + backtracking"""
    # Order vertices by degree (descending)
    order = sorted(range(n), key=lambda v: len(adj[v]), reverse=True)
    colors = {}

    def dfs(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for u in adj[v]:
            if u in colors:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(idx + 1):
                    return True
                del colors[v]
        return False

    return dfs(0)

# Let's try a constructive approach:
# 1. Assign a 3-coloring
# 2. Add edges greedily, avoiding short cycles

def construct_graph():
    best_edges = 0
    best_adj = None
    best_col = None

    for attempt in range(5000):
        # Random 3-coloring with balanced classes
        # Try to balance: 6,6,6
        perm = list(range(n))
        random.shuffle(perm)
        col = [0] * n
        for i in range(6):
            col[perm[i]] = 0
        for i in range(6, 12):
            col[perm[i]] = 1
        for i in range(12, 18):
            col[perm[i]] = 2

        adj = [set() for _ in range(n)]
        edges = []

        # Generate all possible edges between different color classes
        possible = [(i, j) for i in range(n) for j in range(i+1, n) if col[i] != col[j]]
        random.shuffle(possible)

        for u, v in possible:
            # Tentatively add edge
            adj[u].add(v)
            adj[v].add(u)

            # Check for short cycles
            if has_short_cycle(adj, 7):
                adj[u].remove(v)
                adj[v].remove(u)
            else:
                edges.append((u, v))

        if len(edges) > best_edges:
            best_edges = len(edges)
            best_adj = [set(s) for s in adj]
            best_col = col[:]
            if best_edges >= target_edges:
                return best_adj, best_col, best_edges

    return best_adj, best_col, best_edges

random.seed(42)
adj, col, num_edges = construct_graph()
print(f"Best: {num_edges} edges")
if adj:
    edges_list = []
    for i in range(n):
        for j in adj[i]:
            if i < j:
                edges_list.append((i, j))
    print(f"Edges: {sorted(edges_list)}")
    print(f"Coloring: {col}")
    # Verify
    print(f"3-colorable: {is_3_colorable_fast(adj)}")
    print(f"No short cycles: {not has_short_cycle(adj, 7)}")
